def solve(grid, start, goal):
    rows = len(grid)
    if rows == 0:
        return []
    cols = len(grid[0])
    if not (0 <= start[0] < rows and 0 <= start[1] < cols):
        return []
    if not (0 <= goal[0] < rows and 0 <= goal[1] < cols):
        return []
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    directions = [(-1, 0), (0, 1), (1, 0), (0, -1)]

    import heapq
    heap = []
    heapq.heappush(heap, (0, start[0], start[1], [start]))
    processed = set()
    processed.add((start[0], start[1]))

    while heap:
        prio, r, c, path = heapq.heappop(heap)
        if (r, c) == goal:
            return path
        if (r, c) in processed:
            continue
        processed.add((r, c))
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                new_path = path + [(nr, nc)]
                heapq.heappush(heap, (nr + nc, nr, nc, new_path))
    return []

