def solve(grid, start, goal):
    if not grid or not grid[0]:
        return []
    rows, cols = len(grid), len(grid[0])
    if start == goal:
        if grid[start[0]][start[1]] == '.':
            return [start]
        else:
            return []
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    path = [start]
    visited = set([start])

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.' and (r, c) not in visited

    def backtrack(pos):
        if pos == goal:
            return True
        for dr, dc in directions:
            r, c = pos[0] + dr, pos[1] + dc
            if is_valid(r, c):
                visited.add((r, c))
                path.append((r, c))
                if backtrack((r, c)):
                    return True
                path.pop()
                visited.remove((r, c))
        return False

    if backtrack(start):
        return path
    else:
        return []

